      creative_originality: [74, 0.55, "d", "A"],
      // The same Foundation archive page documents a specific, deliberate art-historical reference in his 1950 Spanish fashion series: he "cleverly paid homage to the framing and backgrounds of revered Spanish painters such as Goya and Velazquez by including cats and lapdogs" -- a concrete, describable compositional choice. Single-sourced, kept at moderate confidence.
      aesthetic_sensitivity: [65, 0.48, "d", "A"],
